v.grid(); v.axes();
const c = P.c; // shift in denominator v(x) = x^2 + c
// u(x) = x,  v(x) = x^2 + c
// f = u/v = x/(x^2 + c)
// f' = (u'v - u v')/v^2 = ((x^2+c) - x*2x)/(x^2+c)^2 = (c - x^2)/(x^2+c)^2
const denom = x => x * x + c;
const safe = x => {
  const d = denom(x);
  return Math.abs(d) < 1e-4 ? NaN : d;
};
const f = x => x / safe(x);
const df = x => {
  const d = safe(x);
  return isFinite(d) ? (c - x * x) / (d * d) : NaN;
};
v.fn(f, { color: H.colors.accent, width: 3 });
v.fn(df, { color: H.colors.accent2, width: 2.5, dash: [6, 5] });
